import {
  AccountRole,
  address,
  appendTransactionMessageInstructions,
  createSolanaRpc,
  createTransactionMessage,
  generateKeyPairSigner,
  getAddressEncoder,
  getProgramDerivedAddress,
  pipe,
  setTransactionMessageFeePayerSigner,
  setTransactionMessageLifetimeUsingBlockhash,
  signTransactionMessageWithSigners,
  type Address,
  type Instruction,
  type TransactionSigner,
} from "@solana/kit";

const LOOT = address("LootzMHHCubYFZEgg7kjbyfdsEFBxfPkrUPNzuoExCk");
const PUMP = address("6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P");
const PUMP_FEE = address("pfeeUxB6jkeY1Hxd7CsFCAjcbHA9rWtchMGdZ6VojVZ");
const PAMM = address("pAMMBay6oceH9fJKBRHGP5D4bD4sWpmSwMn52FMfXEA");
const GLOBAL = address("4wTV1YmiEkRvAtNtsSGPtUrqRYQMe5SKy2uB4Jjaxnjf");
const MINT_AUTHORITY = address("TSLvdd1pWpHVjahSpsvCXUbgwsL3JAcvokwaKt1eokM");
const EVENT_AUTHORITY = address("Ce6TQqeHC9p8KetsN6JsjHK7UTZk7nasjjnr7XxXp9F1");
const MAYHEM_PROGRAM = address("MAyhSmzXzV1pTf7LsNkrNwkWKTo4ougAJ1PPg47MD4e");
const MAYHEM_GLOBAL = address("13ec7XdrjF3h3YcqBTFDSReRcUFwbCnJaAQspM4j6DDJ");
const MAYHEM_SOL_VAULT = address("BwWK17cbHxwWBKZkUYvzxLcNQ1YVyaFezduWbtm2de6s");
const SYSTEM = address("11111111111111111111111111111111");
const TOKEN = address("TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA");
const TOKEN_2022 = address("TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb");
const ATA_PROGRAM = address("ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL");
const WSOL = address("So11111111111111111111111111111111111111112");

const text = new TextEncoder();
const enc = getAddressEncoder();

const ro = (account: Address) => ({ address: account, role: AccountRole.READONLY });
const rw = (account: Address) => ({ address: account, role: AccountRole.WRITABLE });
const rwSigner = (signer: TransactionSigner) => ({
  address: signer.address,
  role: AccountRole.WRITABLE_SIGNER,
  signer,
});
function concat(...parts: Uint8Array[]): Uint8Array {
  const out = new Uint8Array(parts.reduce((total, part) => total + part.length, 0));
  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.length;
  }
  return out;
}

function u32(value: number): Uint8Array {
  const bytes = new Uint8Array(4);
  new DataView(bytes.buffer).setUint32(0, value, true);
  return bytes;
}

function u64(value: bigint): Uint8Array {
  const bytes = new Uint8Array(8);
  new DataView(bytes.buffer).setBigUint64(0, value, true);
  return bytes;
}

function borshString(value: string): Uint8Array {
  const bytes = text.encode(value);
  return concat(u32(bytes.length), bytes);
}

async function discriminator(name: string): Promise<Uint8Array> {
  const hash = await crypto.subtle.digest("SHA-256", text.encode(`global:${name}`));
  return new Uint8Array(hash).subarray(0, 8);
}

async function pda(program: Address, seeds: Uint8Array[]): Promise<Address> {
  const [derived] = await getProgramDerivedAddress({ programAddress: program, seeds });
  return derived;
}

async function ata(owner: Address, mint: Address, tokenProgram: Address): Promise<Address> {
  return pda(ATA_PROGRAM, [enc.encode(owner), enc.encode(tokenProgram), enc.encode(mint)]);
}

function productIdBytes(productId: string): Uint8Array {
  const bytes = text.encode(productId);
  if (bytes.length < 1 || bytes.length > 32) throw new Error("Brand id must be 1–32 bytes.");
  return bytes;
}

function linkData(pid: Uint8Array, payout: number, floor: number): Uint8Array {
  const data = new Uint8Array(2 + pid.length + 2);
  data[0] = 3;
  data[1] = pid.length;
  data.set(pid, 2);
  data[2 + pid.length] = payout;
  data[3 + pid.length] = floor;
  return data;
}

/**
 * Pump create_v2. SOL pair, mayhem off, cashback off.
 * Creator fee stays 0, which keeps the pump.fun schedule.
 */
async function createV2Ix(
  payer: TransactionSigner,
  mint: TransactionSigner,
  meta: { name: string; symbol: string; uri: string },
): Promise<Instruction> {
  const bondingCurve = await pda(PUMP, [text.encode("bonding-curve"), enc.encode(mint.address)]);
  const mayhemState = await pda(MAYHEM_PROGRAM, [text.encode("mayhem-state"), enc.encode(mint.address)]);
  return {
    programAddress: PUMP,
    data: concat(
      await discriminator("create_v2"),
      borshString(meta.name),
      borshString(meta.symbol),
      borshString(meta.uri),
      Uint8Array.from(enc.encode(payer.address)),
      new Uint8Array([0, 0]),
      u64(0n),
    ),
    accounts: [
      rwSigner(mint),
      ro(MINT_AUTHORITY),
      rw(bondingCurve),
      rw(await ata(bondingCurve, mint.address, TOKEN_2022)),
      ro(GLOBAL),
      rwSigner(payer),
      ro(SYSTEM),
      ro(TOKEN_2022),
      ro(ATA_PROGRAM),
      rw(MAYHEM_PROGRAM),
      ro(MAYHEM_GLOBAL),
      rw(MAYHEM_SOL_VAULT),
      rw(mayhemState),
      rw(await ata(MAYHEM_SOL_VAULT, mint.address, TOKEN_2022)),
      ro(EVENT_AUTHORITY),
      ro(PUMP),
    ],
  };
}

/** LOOT link_coin. Tag 3. Locks 20% burn / 80% credit before it returns. */
async function linkCoinIx(input: {
  payer: TransactionSigner;
  mint: Address;
  productId: string;
  payout: number;
  floor: number;
}): Promise<Instruction> {
  const mintBytes = enc.encode(input.mint);
  const sharing = await pda(PUMP_FEE, [text.encode("sharing-config"), mintBytes]);
  const pumpVault = await pda(PUMP, [text.encode("creator-vault"), enc.encode(sharing)]);
  const pammVault = await pda(PAMM, [text.encode("creator_vault"), enc.encode(sharing)]);
  return {
    programAddress: LOOT,
    data: linkData(productIdBytes(input.productId), input.payout, input.floor),
    accounts: [
      rwSigner(input.payer),
      ro(await pda(LOOT, [text.encode("brands")])),
      ro(input.mint),
      rw(await pda(PUMP, [text.encode("bonding-curve"), mintBytes])),
      rw(await pda(LOOT, [text.encode("link"), mintBytes])),
      ro(SYSTEM),
      rw(sharing),
      ro(GLOBAL),
      ro(PUMP),
      ro(PUMP_FEE),
      ro(await pda(PUMP_FEE, [text.encode("__event_authority")])),
      ro(await pda(PUMP, [text.encode("__event_authority")])),
      rw(pumpVault),
      rw(await ata(pumpVault, WSOL, TOKEN)),
      ro(WSOL),
      ro(TOKEN),
      ro(ATA_PROGRAM),
      ro(PAMM),
      ro(await pda(PAMM, [text.encode("__event_authority")])),
      rw(pammVault),
      rw(await ata(pammVault, WSOL, TOKEN)),
    ],
  };
}

export async function launchCoin(input: {
  rpcUrl: string;
  payer: TransactionSigner;
  productId: string;
  name: string;
  symbol: string;
  uri: string;
  /** 0 dividends, 1 giveaway. */
  payout: number;
  /** 0 is 100,000 tokens, 1 is 1,000,000, 2 is 10,000,000. */
  floor: number;
}) {
  const rpc = createSolanaRpc(input.rpcUrl);
  const mint = await generateKeyPairSigner();
  const instructions: Instruction[] = [
    await createV2Ix(input.payer, mint, input),
    // A dev buy, if you add one, goes here — still before link_coin.
    await linkCoinIx({
      payer: input.payer,
      mint: mint.address,
      productId: input.productId,
      payout: input.payout,
      floor: input.floor,
    }),
  ];

  const { value: latestBlockhash } = await rpc.getLatestBlockhash().send();
  const message = pipe(
    createTransactionMessage({ version: 0 }),
    (current) => setTransactionMessageFeePayerSigner(input.payer, current),
    (current) => setTransactionMessageLifetimeUsingBlockhash(latestBlockhash, current),
    (current) => appendTransactionMessageInstructions(instructions, current),
  );
  return { mint: mint.address, message: await signTransactionMessageWithSigners(message) };
}
