import { address, createSolanaRpc, getProgramDerivedAddress, type Address } from "@solana/kit";

const LOOT = address("LootzMHHCubYFZEgg7kjbyfdsEFBxfPkrUPNzuoExCk");
const text = new TextEncoder();
const decoder = new TextDecoder();

const REGISTRY_HEADER = 3;
const RECORD_SIZE = 69;
const TAG_REGISTRY = 5;

export type BrandRecord = { productId: string; name: string; color: string; logoUrl: string; bannerUrl: string };

/** One account, every card. Membership is the record. Logo and banner URLs are derived from the product id. */
export async function fetchRegistry(rpcUrl: string): Promise<BrandRecord[]> {
  const registry = await registryAddress();
  const { value } = await createSolanaRpc(rpcUrl).getAccountInfo(registry, { encoding: "base64" }).send();
  if (!value || value.owner !== LOOT) return [];
  return decodeRegistry(value.data[0]);
}

function decodeRegistry(dataBase64: string): BrandRecord[] {
  const data = Uint8Array.from(atob(dataBase64), (char) => char.charCodeAt(0));
  if (data.length < REGISTRY_HEADER || data[0] !== TAG_REGISTRY) return [];
  const count = data[1]! | (data[2]! << 8);
  if (data.length < REGISTRY_HEADER + count * RECORD_SIZE) return [];
  const brands: BrandRecord[] = [];
  for (let i = 0; i < count; i += 1) {
    const rec = REGISTRY_HEADER + i * RECORD_SIZE;
    const productId = readField(data, rec, 32);
    brands.push({
      productId,
      name: readField(data, rec + 33, 32),
      color: readColor(data, rec + 66),
      logoUrl: "/brands/logos/" + productId + ".png",
      bannerUrl: "/brands/banners/" + productId + ".png",
    });
  }
  return brands;
}

function readField(data: Uint8Array, offset: number, cap: number): string {
  const length = data[offset] ?? 0;
  if (length < 1 || length > cap) return "";
  return decoder.decode(data.subarray(offset + 1, offset + 1 + length));
}

function readColor(data: Uint8Array, offset: number): string {
  const hex = (index: number) => (data[offset + index] ?? 0).toString(16).padStart(2, "0");
  return "#" + hex(0) + hex(1) + hex(2);
}

async function registryAddress(): Promise<Address> {
  const [derived] = await getProgramDerivedAddress({
    programAddress: LOOT,
    seeds: [text.encode("brands")],
  });
  return derived;
}
