import { address, createSolanaRpc, getAddressEncoder, getProgramDerivedAddress, type Address } from "@solana/kit";

const LOOT = address("LootzMHHCubYFZEgg7kjbyfdsEFBxfPkrUPNzuoExCk");
const text = new TextEncoder();
const enc = getAddressEncoder();

const LINK_SIZE = 100;
const TAG_LINK = 6;

/** Indexed by the payout byte. */
export const PAYOUTS = ["dividends", "giveaway"] as const;
/** Indexed by the floor byte. Whole tokens a wallet must hold to qualify. */
export const FLOOR_TOKENS = [100_000, 1_000_000, 10_000_000] as const;

export type LinkAccount = {
  address: Address;
  mint: Address;
  productId: string;
  creator: Address;
  payout: (typeof PAYOUTS)[number];
  floorTokens: number;
};

export async function fetchLink(rpcUrl: string, mint: Address): Promise<LinkAccount | null> {
  const link = await linkAddress(mint);
  const { value } = await createSolanaRpc(rpcUrl).getAccountInfo(link, { encoding: "base64" }).send();
  if (!value || value.owner !== LOOT) return null;
  const data = Uint8Array.from(atob(value.data[0]), (char) => char.charCodeAt(0));
  if (data.length !== LINK_SIZE || data[0] !== TAG_LINK) return null;
  const pidLen = data[33] ?? 0;
  if (pidLen < 1 || pidLen > 32) return null;
  const payout = PAYOUTS[data[98] ?? -1];
  const floorTokens = FLOOR_TOKENS[data[99] ?? -1];
  if (payout === undefined || floorTokens === undefined) return null;
  return {
    address: link,
    mint: pubkeyAt(data, 1),
    productId: new TextDecoder().decode(data.subarray(34, 34 + pidLen)),
    creator: pubkeyAt(data, 66),
    payout,
    floorTokens,
  };
}

async function linkAddress(mint: Address): Promise<Address> {
  const [derived] = await getProgramDerivedAddress({
    programAddress: LOOT,
    seeds: [text.encode("link"), enc.encode(mint)],
  });
  return derived;
}

function pubkeyAt(data: Uint8Array, offset: number): Address {
  return enc.decode(data.subarray(offset, offset + 32));
}
